// ShelfLife v2.1 installer. Run from your shelflife folder:  node install-shelflife.js
// Overwrites the app files with the v2 versions. Does NOT touch lib/supabase.ts, .env.local, package.json or node_modules.
const fs = require('fs');
const path = require('path');
const root = process.cwd();
if (!fs.existsSync(path.join(root, 'package.json'))) {
  console.error('Run this inside your shelflife folder (the one with package.json).');
  process.exit(1);
}
const FILES = {
"assets/pattern.png": "",
"assets/logo.png": "",
"assets/buddy.png": "",
"assets/icons/scan.png": "",
"assets/icons/meals.png": "",
"assets/icons/pantry.png": "",
"assets/icons/profile.png": "",
"components/PromptModal.tsx": "",
"components/ItemEditSheet.tsx": "",
"components/Logo.tsx": "",
"components/ui.tsx": "",
"components/TabBar.tsx": "",
"lib/theme.ts": "",
"lib/useEcoStats.ts": "",
"lib/avatar.ts": "",
"lib/recipes.ts": "",
"lib/stats.ts": "",
"lib/shelfLife.ts": "",
"lib/items.ts": "",
"lib/notifications.ts": "",
"lib/nutrition.ts": "",
"lib/categories.ts": "",
"lib/app.tsx": "",
"screens/RecipeScreen.tsx": "",
"screens/CheckInScreen.tsx": "",
"screens/SuggestionsScreen.tsx": "",
"screens/MealsScreen.tsx": "",
"screens/InventoryScreen.tsx": "",
"screens/LoginScreen.tsx": "",
"screens/SettingsScreen.tsx": "",
"screens/ScanScreen.tsx": "",
"screens/CookingScreen.tsx": "",
"screens/EditProfileScreen.tsx": "",
"screens/ReviewScreen.tsx": "",
"screens/OnboardingScreen.tsx": "",
"screens/CircleScreen.tsx": "",
"screens/GroceryScreen.tsx": "",
"screens/ProfileScreen.tsx": "",
"src/app/index.tsx": "",
"supabase/fix_avatars.sql": "",
"supabase/schema.sql": "",
"supabase/schema_v2.sql": "",
"supabase/functions/scan-receipt/index.ts": "",
"src/app/_layout.tsx": "aW1wb3J0IHsgU3RhY2sgfSBmcm9tICdleHBvLXJvdXRlcic7CgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBSb290TGF5b3V0KCkgewogIHJldHVybiA8U3RhY2sgc2NyZWVuT3B0aW9ucz17eyBoZWFkZXJTaG93bjogZmFsc2UgfX0gLz47Cn0K"
};
let n = 0;
for (const [rel, b64] of Object.entries(FILES)) {
  const dest = path.join(root, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, Buffer.from(b64, 'base64'));
  n++;
}
// Remove the Expo starter's tabs folder if it is still there
const tabs = path.join(root, 'src', 'app', '(tabs)');
if (fs.existsSync(tabs)) fs.rmSync(tabs, { recursive: true, force: true });
// Warn about stray copies like "theme (1).ts" or lowercase duplicates
const stray = [];
for (const dir of ['components', 'lib', 'screens', path.join('src', 'app')]) {
  const full = path.join(root, dir);
  if (!fs.existsSync(full)) continue;
  for (const f of fs.readdirSync(full)) {
    const rel = path.join(dir, f).split(path.sep).join('/');
    if (fs.statSync(path.join(full, f)).isDirectory()) continue;
    if (!FILES[rel] && rel !== 'lib/supabase.ts') stray.push(rel);
  }
}
console.log('Wrote ' + n + ' files.');
if (!fs.existsSync(path.join(root, 'lib', 'supabase.ts'))) console.log('WARNING: lib/supabase.ts is missing - put your Supabase client file back.');
if (stray.length) {
  console.log('These extra files are not part of ShelfLife v2. Delete them if they are old copies:');
  for (const s of stray) console.log('  ' + s);
}
console.log('Next: npx expo install @expo-google-fonts/nunito react-native-svg   then   npx expo start --tunnel --clear');
